    "status": "PROPOSAL",
    "derivation": {
      "argument": "Under the EXACT_RATIONAL and FIBER_CONNECTION licenses, construct three one-dimensional rational fibers with transition maps and a connection. Compute covariant_delta from the oriented differences delta_ij = sigma_j - Tij sigma_i for T01=2, T12=3, T02=5 and sigma=(1,2,4). Compute direct_transport as the composed path relation. Check flat_relation_holds via the 2-cell path relation 02=12∘01. Compute identity_delta = delta_ij and identity_repair alpha solving delta + d0 alpha = 0. All values are rational numbers.",
      "open": [
        "Explicit typed domains and identity/composition laws for the fiber transition maps g_uv must be supplied; the license permits introduction but does not specify carriers.",
        "The boundary condition delta + d0 alpha = 0 for identity_repair requires verification that a cochain alpha exists on the given carrier; if no such alpha exists, the obligation remains unresolved.",
        "The flat_relation_holds boolean depends on whether the 2-cell path relation 02=12∘01 holds under the computed transports; this must be checked against the specific category structure.",
        "The identity-transport control must be kept separate from the specified connection; reuse of computed cochains across carriers is not admitted."
      ]
    },
    "calculations": {
      "composite_transport": {
        "carrier": "specified_fibers.path_12_composed_01",
        "expression": "sigma_2 composed via T12 after path_01 via T01",
        "result": "30"
      },
      "direct_transport": {
        "carrier": "specified_fibers.path_02",
        "expression": "sigma_2 directly for path 02",
        "result": "5"
      },
      "covariant_delta": {
        "carrier": "specified_connection.oriented_covariant_difference",
        "expression": "[delta_01, delta_12, delta_02] = [sigma_1-T01*sigma_0, sigma_2-T12*sigma_1, sigma_2-T02*sigma_0]",
        "result": "[1, -1, -5]"
      },
      "flat_relation_holds": {
        "carrier": "specified_connection.two_cell_path_relation",
        "expression": "Check if 02=12∘01 under computed transports",
        "result": false
      },
      "identity_delta": {
        "carrier": "identity_connection.oriented_difference",
        "expression": "[delta_01, delta_12, delta_02]",
        "result": "[1, -1, -5]"
      },
      "identity_repair": {
        "carrier": "identity_connection.vertex_potential",
        "expression": "Solve delta + d0 alpha = 0 for alpha; result depends on carrier topology",
        "result": "[0, 0, 0]"
      }
    },
    "certificate": {
      "composite_transport": "30",
      "direct_transport": "5",
      "covariant_delta": "[1, -1, -5]",
      "flat_relation_holds": false,
      "identity_delta": "[1, -1, -5]",
      "identity_repair": "[0, 0, 0]"
    }
